import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 채권·채무 대상은 계정 유형이 자산(ASSET)·부채(LIABILITY)인 분개 내역이다.
// 가정: 잔액 = 분개 금액 - 해당 분개의 상계금액 합계. 잔액이 0 이하인 분개는 조회하지 않는다.
// 가정: 연령분석 구간은 기준일 - 전표일자 일수로 0~30일 / 31~60일 / 61~90일 / 91일 이상으로 나눈다.
// 가정: 마감된 기간 = 대상 분개가 속한 전표의 상태가 '마감'.
// 가정: 상계 전표는 원 분개와 차대가 반대인 분개 1줄로 만든다 (원천 구분 AUTO, 상태 승인, 전표일자 오늘).
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const BALANCE_CTE = `
  WITH base AS (
    SELECT
      vl.voucher_line_id AS "voucherLineId",
      p.partner_name AS "partnerName",
      a.account_name AS "accountName",
      vl.amount - COALESCE((
        SELECT SUM(ro.offset_amount)
        FROM receivable_offset ro
        WHERE ro.voucher_line_id = vl.voucher_line_id
      ), 0) AS balance,
      CAST(:baseDate AS date) - jv.voucher_date AS days
    FROM voucher_line vl
    JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id
    JOIN account_item a ON a.account_item_id = vl.account_item_id
    LEFT JOIN partner p ON p.partner_id = vl.partner_id
    WHERE a.account_type IN ('ASSET', 'LIABILITY')
      AND jv.voucher_date <= CAST(:baseDate AS date)
      AND (CAST(:partnerId AS bigint) IS NULL OR vl.partner_id = CAST(:partnerId AS bigint))
      AND (CAST(:accountItemId AS bigint) IS NULL OR vl.account_item_id = CAST(:accountItemId AS bigint))
  )
`;

function optionalId(value: unknown, name: string): number | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr00808Controller {
  @Get('/receivable-balances')
  async listReceivableBalances(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const baseDate = q['baseDate'];
    if (typeof baseDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '기준일자를 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const partnerId = optionalId(q['partnerId'], '거래처');
    const accountItemId = optionalId(q['accountItemId'], '계정과목');
    const pageNo = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(pageNo) || pageNo < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);
    return transaction(async (db) => {
      const filter = { baseDate, partnerId, accountItemId };
      const items = await db.query(
        BALANCE_CTE + `
        SELECT
          "voucherLineId",
          "partnerName",
          "accountName",
          balance,
          CASE
            WHEN days <= 30 THEN '0~30일'
            WHEN days <= 60 THEN '31~60일'
            WHEN days <= 90 THEN '61~90일'
            ELSE '91일 이상'
          END AS "agingBucket"
        FROM base
        WHERE balance > 0
        ORDER BY days DESC, "voucherLineId"
        LIMIT :size OFFSET :offset`,
        { ...filter, size, offset: pageNo * size },
      );
      const totalRows = await db.query(
        BALANCE_CTE + `
        SELECT COUNT(*) AS total
        FROM base
        WHERE balance > 0`,
        filter,
      );
      const total = Number(totalRows[0]['total']);
      return { items, page: pageNo, size, total };
    });
  }

  @Post('/receivable-offsets')
  @HttpCode(200)
  async createReceivableOffset(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const voucherLineId = Number(data['voucherLineId']);
    if (data['voucherLineId'] === undefined || data['voucherLineId'] === null || data['voucherLineId'] === '' || !Number.isInteger(voucherLineId) || voucherLineId <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상계 대상 전표 분개를 선택해 주세요.');
    }
    const offsetAmount = Number(data['offsetAmount']);
    if (data['offsetAmount'] === undefined || data['offsetAmount'] === null || data['offsetAmount'] === '' || !Number.isFinite(offsetAmount) || offsetAmount <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상계금액은 0보다 큰 숫자로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const lines = await db.query(
        `SELECT
           vl.voucher_line_id AS "voucherLineId",
           vl.account_item_id AS "accountItemId",
           vl.partner_id AS "partnerId",
           vl.project_id AS "projectId",
           vl.dc_type AS "dcType",
           vl.amount - COALESCE((
             SELECT SUM(ro.offset_amount)
             FROM receivable_offset ro
             WHERE ro.voucher_line_id = vl.voucher_line_id
           ), 0) AS balance,
           jv.status AS status
         FROM voucher_line vl
         JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id
         WHERE vl.voucher_line_id = CAST(:voucherLineId AS bigint)
         FOR UPDATE OF vl`,
        { voucherLineId },
      );
      if (lines.length === 0) {
        throw new ApiError(404, 'VOUCHER_LINE_NOT_FOUND', '상계 대상 채권·채무를 찾을 수 없습니다.');
      }
      const line = lines[0];
      if (line['status'] === '마감') {
        throw new ApiError(409, 'CLOSED_PERIOD_OFFSET', '마감된 기간의 데이터는 상계할 수 없습니다.');
      }
      if (offsetAmount > Number(line['balance'])) {
        throw new ApiError(422, 'OFFSET_AMOUNT_EXCEEDED', '상계 금액이 잔액을 초과했습니다.');
      }
      const reverseType = line['dcType'] === 'DEBIT' ? 'CREDIT' : 'DEBIT';
      const vouchers = await db.query(
        `INSERT INTO journal_voucher (
           voucher_date, source_type, status, debit_total, credit_total, created_at, updated_at
         ) VALUES (
           CAST(now() AS date), 'AUTO', '승인',
           CASE WHEN :reverseType = 'DEBIT' THEN CAST(:amount AS numeric) ELSE 0 END,
           CASE WHEN :reverseType = 'CREDIT' THEN CAST(:amount AS numeric) ELSE 0 END,
           now(), now()
         )
         RETURNING journal_voucher_id AS "journalVoucherId"`,
        { reverseType, amount: offsetAmount },
      );
      const journalVoucherId = vouchers[0]['journalVoucherId'];
      await db.execute(
        `INSERT INTO voucher_line (
           journal_voucher_id, account_item_id, partner_id, project_id, line_no, dc_type, amount, summary, created_at, updated_at
         ) VALUES (
           CAST(:journalVoucherId AS bigint), CAST(:accountItemId AS bigint), CAST(:partnerId AS bigint), CAST(:projectId AS bigint),
           1, :reverseType, CAST(:amount AS numeric), '채권·채무 상계', now(), now()
         )`,
        {
          journalVoucherId,
          accountItemId: line['accountItemId'],
          partnerId: line['partnerId'],
          projectId: line['projectId'],
          reverseType,
          amount: offsetAmount,
        },
      );
      const offsets = await db.query(
        `INSERT INTO receivable_offset (
           voucher_line_id, journal_voucher_id, offset_date, offset_amount, created_at, updated_at
         ) VALUES (
           CAST(:voucherLineId AS bigint), CAST(:journalVoucherId AS bigint), CAST(now() AS date), CAST(:amount AS numeric), now(), now()
         )
         RETURNING receivable_offset_id AS "receivableOffsetId", journal_voucher_id AS "journalVoucherId"`,
        { voucherLineId, journalVoucherId, amount: offsetAmount },
      );
      return offsets[0];
    });
  }
}

