import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  NumberInput,
  DateInput,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr00808Page({ role, notify }: PageProps) {
  const today = new Date().toISOString().slice(0, 10);
  const [baseDate, setBaseDate] = useState<string>(today);
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({ baseDate: today });
  const [page, setPage] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);
  const [amount, setAmount] = useState<number | string>('');

  const { data, error, reload } = useData<Page>(async () => {
    return call<Page>('GET', '/receivable-balances', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page, role]);

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageSum = rows.reduce((sum, r) => sum + Number(r['balance'] ?? 0), 0);

  function search() {
    setPage(0);
    setApplied({ baseDate, partnerId, accountItemId });
  }

  function reset() {
    setBaseDate(today);
    setPartnerId('');
    setAccountItemId('');
    setPage(0);
    setApplied({ baseDate: today });
  }

  function openOffset(row: Row) {
    setAmount('');
    setTarget(row);
  }

  async function submitOffset() {
    if (!target) {
      return;
    }
    const value = Number(amount);
    if (amount === '' || !Number.isFinite(value) || value <= 0) {
      throw new Error('상계금액을 0보다 큰 숫자로 입력해 주세요.');
    }
    if (value > Number(target['balance'])) {
      throw new Error('상계 금액이 잔액을 초과했습니다.');
    }
    await call('POST', '/receivable-offsets', role, {
      voucherLineId: target['voucherLineId'],
      offsetAmount: value,
    });
    notify('상계 처리했습니다.');
    setTarget(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['채권·채무 건수', <Num value={total} />]]} />
      </section>
      <section className="box span-4">
        <h2>현재 쪽 잔액</h2>
        <Tiles items={[['잔액 합계', <Num value={pageSum} />]]} />
      </section>
      <section className="box span-12">
        <h2>채권·채무 잔액</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="기준일자" required>
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} />
          </Field>
          <Field label="계정과목">
            <LookupSelect table="account_item" role={role} value={accountItemId} onChange={setAccountItemId} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          rows={rows}
          empty="조회된 채권·채무가 없습니다."
          columns={[
            { key: 'voucherLineId', label: '전표 분개 내역 ID' },
            { key: 'partnerName', label: '거래처 명칭' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'balance', label: '채권·채무 잔액', render: (r) => <Num value={r['balance']} /> },
            { key: 'agingBucket', label: '연령분석 기간 구간', render: (r) => <Badge value={r['agingBucket']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (
                <button type="button" onClick={() => openOffset(r)}>
                  상계
                </button>
              ),
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {target ? (
        <Drawer title="채권·채무 상계" onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['전표 분개 내역 ID', String(target['voucherLineId'])],
              ['거래처 명칭', String(target['partnerName'] ?? '')],
              ['계정과목 명칭', String(target['accountName'] ?? '')],
              ['채권·채무 잔액', <Num value={target['balance']} />],
              ['연령분석 기간 구간', <Badge value={target['agingBucket']} />],
            ]}
          />
          <Form onSubmit={submitOffset} submit="상계 처리">
            <Field label="상계금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
